@Test
public void testGetValueFromResultSet_BinaryStream() throws Exception {
    ValueMetaJson vm = new ValueMetaJson("j");
    IDatabase idb = mock(IDatabase.class);
    ResultSet rs = mock(ResultSet.class);
    String json = "{\"x\":42}";
    InputStream in = new ByteArrayInputStream(json.getBytes(java.nio.charset.StandardCharsets.UTF_8));
    // index+1 = 1
    when(rs.getBinaryStream(1)).thenReturn(in);
