 */
@Test
void folderCreation_Relative_Simple() throws Exception {
    System.setProperty(SftpClient.ENV_PARAM_USERAUTH_GSSAPI, "yes");
    SftpClient client = spy(new SftpClient(server, port, username) {

        @Override
        JSch createJSch() {
            return jSch;
        }
    });
