@Test
void testSetCalendar() {
    SalesforceConnection conn = mock(SalesforceConnection.class, Mockito.CALLS_REAL_METHODS);
    // Test valid data
    try {
        conn.setCalendar(new Random().nextInt(SalesforceConnectionUtils.recordsFilterDesc.length), new GregorianCalendar(2016, Calendar.JANUARY, 1), new GregorianCalendar(2016, Calendar.JANUARY, 31));
        // No errors detected
    } catch (HopException e) {
        fail();
    }
    // Test reversed dates (should fail)
    try {
        conn.setCalendar(new Random().nextInt(SalesforceConnectionUtils.recordsFilterDesc.length), new GregorianCalendar(2016, Calendar.JANUARY, 31), new GregorianCalendar(2016, Calendar.JANUARY, 1));
        fail();
    } catch (HopException expected) {
        // Ignore, expected result
    }
    // Test null start date (should fail)
    try {
        conn.setCalendar(new Random().nextInt(SalesforceConnectionUtils.recordsFilterDesc.length), null, new GregorianCalendar(2016, Calendar.JANUARY, 31));
        fail();
    } catch (HopException expected) {
        // Ignore, expected result
    }
    // Test null end date (should fail)
    try {
        conn.setCalendar(new Random().nextInt(SalesforceConnectionUtils.recordsFilterDesc.length), new GregorianCalendar(2016, Calendar.JANUARY, 1), null);
        fail();
    } catch (HopException expected) {
        // Ignore, expected result
    }
}

// Hop-15973
@Test
void testGetRecordValue() throws Exception {
    // Hop-15973
    SalesforceConnection conn = mock(SalesforceConnection.class, Mockito.CALLS_REAL_METHODS);
    SObject sObject = new SObject();
    sObject.setName(new QName(Constants.PARTNER_SOBJECT_NS, "sObject"));
    SObject testObject = createObject("field", "value");
    sObject.addField("field", testObject);
    assertEquals("value", conn.getRecordValue(sObject, "field"), "Get value of simple record");
    SObject parentObject = createObject("parentField", null);
    sObject.addField("parentField", parentObject);
    SObject childObject = createObject("subField", "subValue");
    parentObject.addField("subField", childObject);
    assertEquals("subValue", conn.getRecordValue(sObject, "parentField.subField"), "Get value of record with hierarchy");
    XmlObject nullObject = new XmlObject(new QName("nullField"));
    sObject.addField("nullField", nullObject);
    assertEquals(null, conn.getRecordValue(sObject, "nullField.childField"), "Get null value when relational query id is null");
}

